function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function inferOperation(input) {
  if (input.operation) return clean(input.operation);

  if (input.schema_version === 'dalia.m3_to_m4.memory_update.v1') {
    return 'upsert_session_memory';
  }

  if (input.memory_update) {
    return 'upsert_session_memory';
  }

  if (input.lookup || input.current_turn) {
    return 'get_session_memory';
  }

  if (input.close_request || input.session_summary_request) {
    return 'close_session_summary';
  }

  if (input.operation === 'save_vector_memory' || input.vector_memory_save_request) {
    return 'save_vector_memory';
  }

  if (input.operation === 'retrieve_vector_memory' || input.vector_memory_retrieve_request) {
    return 'retrieve_vector_memory';
  }

  if (input.operation === 'get_turn_context') {
    return 'get_turn_context';
  }

  return 'unknown';
}

function normalizeLookup(input) {
  const lookup = input.lookup || {};
  const trace = input.trace || input.m2_input?.trace || {};
  const context = input.context || input.m2_input?.context || {};
  const memoryUpdate = input.memory_update || {};

  return {
    session_id: clean(
      lookup.session_id ||
      trace.session_id ||
      memoryUpdate.session_id ||
      input.session_id
    ),
    conversation_id: clean(
      lookup.conversation_id ||
      trace.conversation_id ||
      memoryUpdate.conversation_id ||
      input.conversation_id
    ),
    user_id: clean(
      lookup.user_id ||
      context.user_id ||
      memoryUpdate.user_id ||
      input.user_id
    ),
    channel: clean(
      lookup.channel ||
      context.channel ||
      memoryUpdate.channel ||
      input.channel
    )
  };
}

function normalizeCurrentTurn(input) {
  const current = input.current_turn || input.input || input.message || {};
  const memoryUpdate = input.memory_update || {};

  return {
    message_id: clean(current.message_id || current.id),
    type: clean(current.type),
    text: clean(
      current.text ||
      current.normalized_text ||
      memoryUpdate.last_user_message
    ),
    timestamp: clean(current.timestamp || memoryUpdate.updated_at)
  };
}

function normalizeMemoryUpdate(input) {
  const memoryUpdate = input.memory_update || {};

  return {
    conversation_id: clean(memoryUpdate.conversation_id),
    session_id: clean(memoryUpdate.session_id),
    user_id: clean(memoryUpdate.user_id),
    channel: clean(memoryUpdate.channel),
    display_name: clean(memoryUpdate.display_name),

    intent: clean(memoryUpdate.intent),
    advisor_mode: clean(memoryUpdate.advisor_mode),
    last_user_message: clean(memoryUpdate.last_user_message),
    response_type: clean(memoryUpdate.response_type),
    next_step: clean(memoryUpdate.next_step),

    product_consulted: clean(memoryUpdate.product_consulted),
    last_products_recommended: Array.isArray(memoryUpdate.last_products_recommended)
      ? memoryUpdate.last_products_recommended
      : [],

    category_consulted: clean(memoryUpdate.category_consulted),
    preference_detected: clean(memoryUpdate.preference_detected),
    city_detected: clean(memoryUpdate.city_detected),

    catalog_matched: Boolean(memoryUpdate.catalog_matched),
    purchase_signal_detected: Boolean(memoryUpdate.purchase_signal_detected),
    handoff_suggested: Boolean(memoryUpdate.handoff_suggested),

    updated_at: clean(memoryUpdate.updated_at) || new Date().toISOString()
  };
}

function normalizeCloseRequest(input) {
  const closeRequest = input.close_request || input.session_summary_request || {};
  const lookup = normalizeLookup(input);

  return {
    session_id: clean(closeRequest.session_id || lookup.session_id),
    conversation_id: clean(closeRequest.conversation_id || lookup.conversation_id),
    user_id: clean(closeRequest.user_id || lookup.user_id),
    close_reason: clean(closeRequest.close_reason || 'manual_or_timeout'),
    requested_at: clean(closeRequest.requested_at) || new Date().toISOString()
  };
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};

const operation = inferOperation(input);

const m4Request = {
  schema_version: config.contracts?.request_schema_version || 'dalia.m4.memory_request.v1',
  operation,

  lookup: normalizeLookup(input),
  current_turn: normalizeCurrentTurn(input),
  memory_update: normalizeMemoryUpdate(input),
  close_request: normalizeCloseRequest(input),

  requested_at: new Date().toISOString(),
  passthrough: input.passthrough || input
};

return [
  {
    json: {
      ...input,
      m4_request: m4Request
    }
  }
];

function isEmpty(value) {
  return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};
const request = input.m4_request || {};

const errors = [];
const warnings = [];

const supportedOperations = config.supported_operations || [];

if (!supportedOperations.includes(request.operation)) {
  errors.push('unsupported_operation');
}

if (request.operation === 'get_session_memory') {
  if (isEmpty(request.lookup?.session_id)) {
    errors.push('missing_lookup_session_id');
  }

  if (isEmpty(request.lookup?.user_id)) {
    warnings.push('missing_lookup_user_id');
  }
}

if (request.operation === 'upsert_session_memory') {
  const memory = request.memory_update || {};

  if (isEmpty(memory.session_id)) {
    errors.push('missing_memory_session_id');
  }

  if (isEmpty(memory.conversation_id)) {
    errors.push('missing_memory_conversation_id');
  }

  if (isEmpty(memory.user_id)) {
    errors.push('missing_memory_user_id');
  }

  if (
    isEmpty(memory.product_consulted) &&
    (!Array.isArray(memory.last_products_recommended) || memory.last_products_recommended.length === 0) &&
    isEmpty(memory.preference_detected) &&
    isEmpty(memory.city_detected)
  ) {
    warnings.push('memory_update_has_no_commercial_signal');
  }
}

if (request.operation === 'close_session_summary') {
  if (isEmpty(request.close_request?.session_id)) {
    errors.push('missing_close_session_id');
  }
}

return [
  {
    json: {
      ...input,
      m4_request_validation: {
        valid: errors.length === 0,
        errors,
        warnings
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      branch_context: {
        branch: 'get_session_memory',
        configured_in_task: 1,
        next_task: 3,
        status: 'branch_entry_ready'
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      branch_context: {
        branch: 'upsert_session_memory',
        configured_in_task: 1,
        next_task: 2,
        status: 'branch_entry_ready'
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      branch_context: {
        branch: 'close_session_summary',
        configured_in_task: 1,
        next_task: 5,
        status: 'branch_entry_ready'
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      schema_version: 'dalia.m4.memory_result.v1',
      operation: input.m4_request?.operation || 'unknown',
      success: false,
      result_type: 'invalid_request',
      errors: input.m4_request_validation?.errors || ['unsupported_operation'],
      warnings: input.m4_request_validation?.warnings || [],
      session_memory: {
        found: false,
        usable: false,
        reason: 'invalid_m4_request'
      }
    }
  }
];

function nowIso() {
  return new Date().toISOString();
}

function isValidDate(str) {
  if (!str) return false;
  return !isNaN(new Date(str).getTime());
}

function addHours(date, hours) {
  const d = new Date(date);
  if (isNaN(d.getTime())) return nowIso();
  const h = parseInt(hours, 10);
  d.setHours(d.getHours() + (isNaN(h) ? 24 : h));
  return d.toISOString();
}

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function normalizeProductList(value, maxItems = 5) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map(item => {
        if (typeof item === 'string') {
          return {
            product_id: '',
            display_name: item,
            category: '',
            color: ''
          };
        }

        return {
          product_id: item.product_id || item.sku || '',
          display_name: item.display_name || item.product_name || '',
          category: item.category || '',
          color: item.color || ''
        };
      })
      .filter(item => item.display_name)
      .slice(0, maxItems);
  }

  return [];
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};
const request = input.m4_request || {};
const memoryUpdate = request.memory_update || {};

const rawUpdatedAt = clean(memoryUpdate.updated_at);
const updatedAt = isValidDate(rawUpdatedAt) ? rawUpdatedAt : nowIso();
const createdAt = updatedAt;
const expiresAt = addHours(
  updatedAt,
  config.session_policy?.session_ttl_hours || 24
);

const maxProducts =
  config.session_policy?.max_products_recommended || 5;

const lastProductsRecommended = normalizeProductList(
  memoryUpdate.last_products_recommended,
  maxProducts
);

const productConsulted = clean(memoryUpdate.product_consulted);

const currentFocusProducts =
  lastProductsRecommended.length > 0
    ? lastProductsRecommended
    : productConsulted
      ? [{ product_id: '', display_name: productConsulted, category: '', color: '' }]
      : [];

const sessionMemoryCandidate = {
  schema_version:
    config.contracts?.session_memory_schema_version ||
    'dalia.m4.session_memory.v1',

  identity: {
    session_id: clean(memoryUpdate.session_id),
    conversation_id: clean(memoryUpdate.conversation_id),
    user_id: clean(memoryUpdate.user_id),
    channel: clean(memoryUpdate.channel),
    display_name: clean(memoryUpdate.display_name)
  },

  commercial_context: {
    last_intent: clean(memoryUpdate.intent),
    last_advisor_mode: clean(memoryUpdate.advisor_mode),
    last_user_message: clean(memoryUpdate.last_user_message),
    last_response_type: clean(memoryUpdate.response_type),
    last_next_step: clean(memoryUpdate.next_step),

    last_product_consulted: productConsulted,
    last_products_recommended: lastProductsRecommended,
    last_category_consulted: clean(memoryUpdate.category_consulted),
    last_preference_detected: clean(memoryUpdate.preference_detected),
    last_city_detected: clean(memoryUpdate.city_detected),

    catalog_matched: Boolean(memoryUpdate.catalog_matched),
    last_purchase_signal_detected: Boolean(memoryUpdate.purchase_signal_detected),
    last_handoff_suggested: Boolean(memoryUpdate.handoff_suggested)
  },

  reference_context: {
    current_focus_product: productConsulted,
    current_focus_products: currentFocusProducts,
    current_focus_category: clean(memoryUpdate.category_consulted),
    can_resolve_contextual_references:
      Boolean(productConsulted) || currentFocusProducts.length > 0,
    supported_references:
      config.reference_resolution?.supported_references || []
  },

  recent_turns: [
    {
      at: updatedAt,
      user_message: clean(memoryUpdate.last_user_message),
      intent: clean(memoryUpdate.intent),
      advisor_mode: clean(memoryUpdate.advisor_mode),
      response_type: clean(memoryUpdate.response_type),
      product_consulted: productConsulted,
      preference_detected: clean(memoryUpdate.preference_detected),
      city_detected: clean(memoryUpdate.city_detected)
    }
  ].filter(turn =>
    turn.user_message ||
    turn.intent ||
    turn.product_consulted ||
    turn.preference_detected ||
    turn.city_detected
  ),

  lifecycle: {
    session_status:
      config.session_policy?.default_session_status || 'active',
    created_at: createdAt,
    updated_at: updatedAt,
    expires_at: expiresAt
  },

  control: {
    source_module: 'M3',
    source_contract: input.schema_version || '',
    update_reason: 'm3_response_generated',
    storage_provider: config.storage?.provider || 'supabase',
    storage_table: config.storage?.table || 'dalia_session_memory'
  }
};

return [
  {
    json: {
      ...input,
      session_memory_candidate: sessionMemoryCandidate
    }
  }
];

function isEmpty(value) {
 return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};
const memory = input.session_memory_candidate || {};

const errors = [];
const warnings = [];

const expectedSchema =
 config.contracts?.session_memory_schema_version ||
 'dalia.m4.session_memory.v1';

if (memory.schema_version !== expectedSchema) {
 errors.push('invalid_session_memory_schema_version');
}

const identity = memory.identity || {};

const requiredIdentityFields =
 config.required_identity_fields || [
   'session_id',
   'conversation_id',
   'user_id'
 ];

for (const field of requiredIdentityFields) {
 if (isEmpty(identity[field])) {
   errors.push(`missing_identity_${field}`);
 }
}

if (!memory.commercial_context) {
 errors.push('missing_commercial_context');
}

if (!memory.reference_context) {
 errors.push('missing_reference_context');
}

if (!memory.lifecycle) {
 errors.push('missing_lifecycle');
}

if (!Array.isArray(memory.recent_turns)) {
 errors.push('recent_turns_must_be_array');
}

const commercial = memory.commercial_context || {};

if (
 isEmpty(commercial.last_product_consulted) &&
 (!Array.isArray(commercial.last_products_recommended) ||
   commercial.last_products_recommended.length === 0) &&
 isEmpty(commercial.last_preference_detected) &&
 isEmpty(commercial.last_city_detected)
) {
 warnings.push('no_minimum_commercial_memory_signal');
}

return [
 {
   json: {
     ...input,
     session_memory_validation: {
       valid: errors.length === 0,
       errors,
       warnings
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function ensureArray(value) {
 if (Array.isArray(value)) return value;
 if (!value) return [];
 return [value];
}

const input = items[0]?.json || {};
const memory = input.session_memory_candidate || {};
const validation = input.session_memory_validation || {};

if (!validation.valid) {
 return [
   {
     json: {
       ...input,
       persistence_status: {
         should_persist: false,
         reason: 'session_memory_validation_failed',
         errors: validation.errors || []
       }
     }
   }
 ];
}

const identity = memory.identity || {};
const commercial = memory.commercial_context || {};
const reference = memory.reference_context || {};
const lifecycle = memory.lifecycle || {};
const control = memory.control || {};

const supabaseRow = {
 session_id: clean(identity.session_id),
 conversation_id: clean(identity.conversation_id),
 user_id: clean(identity.user_id),
 channel: clean(identity.channel),
 display_name: clean(identity.display_name),

 session_status: clean(lifecycle.session_status) || 'active',

 last_intent: clean(commercial.last_intent),
 last_advisor_mode: clean(commercial.last_advisor_mode),
 last_user_message: clean(commercial.last_user_message),
 last_response_type: clean(commercial.last_response_type),
 last_next_step: clean(commercial.last_next_step),

 last_product_consulted: clean(commercial.last_product_consulted),
 last_products_recommended: ensureArray(commercial.last_products_recommended),

 last_category_consulted: clean(commercial.last_category_consulted),
 last_preference_detected: clean(commercial.last_preference_detected),
 last_city_detected: clean(commercial.last_city_detected),

 catalog_matched: Boolean(commercial.catalog_matched),
 last_purchase_signal_detected: Boolean(commercial.last_purchase_signal_detected),
 last_handoff_suggested: Boolean(commercial.last_handoff_suggested),

 current_focus_product: clean(reference.current_focus_product),
 current_focus_products: ensureArray(reference.current_focus_products),
 can_resolve_contextual_references:
   Boolean(reference.can_resolve_contextual_references),

 recent_turns: ensureArray(memory.recent_turns),

 schema_version: clean(memory.schema_version),
 source_module: clean(control.source_module),
 source_contract: clean(control.source_contract),
 update_reason: clean(control.update_reason),

 memory_payload: memory,

 created_at: lifecycle.created_at || new Date().toISOString(),
 expires_at: lifecycle.expires_at || null
};

return [
 {
   json: {
     ...input,
     supabase_row: supabaseRow,
     persistence_status: {
       should_persist: true,
       reason: 'valid_session_memory_candidate'
     }
   }
 }
];

function isEmpty(value) {
 if (value === null || value === undefined) return true;
 if (typeof value === 'string' && value.trim() === '') return true;
 if (Array.isArray(value) && value.length === 0) return true;
 return false;
}

function preferNew(newValue, oldValue) {
 return isEmpty(newValue) ? oldValue : newValue;
}

function ensureArray(value) {
 if (Array.isArray(value)) return value;
 if (!value) return [];
 return [value];
}

function mergeRecentTurns(existingTurns, newTurns, maxTurns = 5) {
 return [
   ...ensureArray(existingTurns),
   ...ensureArray(newTurns)
 ]
   .filter(Boolean)
   .slice(-maxTurns);
}

const existing = items[0]?.json || {};
const prepared = $('Prepare Supabase Memory Row').first().json || {};
const incoming = prepared.supabase_row || {};
const config = prepared.memory_service_config || {};

const maxTurns =
 config.session_policy?.max_recent_turns || 5;

const merged = {
 ...existing,

 session_id: incoming.session_id,
 conversation_id: preferNew(incoming.conversation_id, existing.conversation_id),
 user_id: preferNew(incoming.user_id, existing.user_id),
 channel: preferNew(incoming.channel, existing.channel),
 display_name: preferNew(incoming.display_name, existing.display_name),

 session_status: preferNew(incoming.session_status, existing.session_status),

 last_intent: preferNew(incoming.last_intent, existing.last_intent),
 last_advisor_mode: preferNew(incoming.last_advisor_mode, existing.last_advisor_mode),
 last_user_message: preferNew(incoming.last_user_message, existing.last_user_message),
 last_response_type: preferNew(incoming.last_response_type, existing.last_response_type),
 last_next_step: preferNew(incoming.last_next_step, existing.last_next_step),

 last_product_consulted: preferNew(incoming.last_product_consulted, existing.last_product_consulted),

 last_products_recommended: isEmpty(incoming.last_products_recommended)
   ? ensureArray(existing.last_products_recommended)
   : ensureArray(incoming.last_products_recommended),

 last_category_consulted: preferNew(incoming.last_category_consulted, existing.last_category_consulted),
 last_preference_detected: preferNew(incoming.last_preference_detected, existing.last_preference_detected),
 last_city_detected: preferNew(incoming.last_city_detected, existing.last_city_detected),

 catalog_matched: Boolean(incoming.catalog_matched || existing.catalog_matched),
 last_purchase_signal_detected:
   Boolean(incoming.last_purchase_signal_detected || existing.last_purchase_signal_detected),
 last_handoff_suggested:
   Boolean(incoming.last_handoff_suggested || existing.last_handoff_suggested),

 current_focus_product: preferNew(incoming.current_focus_product, existing.current_focus_product),

 current_focus_products: isEmpty(incoming.current_focus_products)
   ? ensureArray(existing.current_focus_products)
   : ensureArray(incoming.current_focus_products),

 can_resolve_contextual_references:
   Boolean(incoming.can_resolve_contextual_references || existing.can_resolve_contextual_references),

 recent_turns: mergeRecentTurns(
   existing.recent_turns,
   incoming.recent_turns,
   maxTurns
 ),

 schema_version: preferNew(incoming.schema_version, existing.schema_version),
 source_module: preferNew(incoming.source_module, existing.source_module),
 source_contract: preferNew(incoming.source_contract, existing.source_contract),
 update_reason: preferNew(incoming.update_reason, existing.update_reason),

 memory_payload: incoming.memory_payload || existing.memory_payload || {},

 created_at: existing.created_at || incoming.created_at,
 expires_at: preferNew(incoming.expires_at, existing.expires_at)
};

return [
 {
   json: {
     supabase_row: merged,
     persistence_operation: 'update'
   }
 }
];

const prepared = $('Prepare Supabase Memory Row').first().json || {};
const row = prepared.supabase_row || {};

return [
 {
   json: {
     schema_version: 'dalia.m4.memory_result.v1',
     operation: 'upsert_session_memory',
     result_type: 'persistence_result',
     success: true,
     persistence_operation: 'update',
     storage: {
       provider: 'supabase',
       table: 'dalia_session_memory'
     },
     session_id: row.session_id || '',
     conversation_id: row.conversation_id || '',
     user_id: row.user_id || '',
     validation: prepared.session_memory_validation || {},
     persistence_status: prepared.persistence_status || {},
     updated_at: new Date().toISOString()
   }
 }
];

const prepared = $('Prepare Supabase Memory Row').first().json || {};
const row = prepared.supabase_row || {};

return [
 {
