   }
 }
];

function isEmpty(value) {
 return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const request = input.m4_request || {};

const errors = [];
const warnings = [];

if (request.operation !== 'get_session_memory') {
 errors.push('invalid_branch_operation');
}

if (isEmpty(request.lookup?.session_id)) {
 errors.push('missing_lookup_session_id');
}

if (isEmpty(request.lookup?.user_id)) {
 warnings.push('missing_lookup_user_id');
}

if (isEmpty(request.lookup?.conversation_id)) {
