const input = items[0]?.json || {};
const request = input.m4_request || {};
const validation = input.lookup_validation || {};

return [
  {
    json: {
      schema_version: 'dalia.m4.memory_result.v1',
      operation: 'get_session_memory',
      result_type: 'memory_lookup_result',
      success: false,
      session_memory: {
        found: false,
        usable: false,
        reason: 'invalid_lookup_request',
        identity: {
          session_id: request.lookup?.session_id || '',
          conversation_id: request.lookup?.conversation_id || '',
          user_id: request.lookup?.user_id || '',
          channel: request.lookup?.channel || ''
        },
        commercial_context: {},
        reference_context: {
          can_resolve_contextual_references: false,
          current_focus_product: '',
          current_focus_products: []
        },
        recent_turns: [],
        lifecycle: {},
        control: {
          source: 'supabase',
          table: input.memory_service_config?.storage?.table || 'dalia_session_memory'
        }
      },
      validation,
      passthrough: request.passthrough || {}
    }
  }
];

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function ensureArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  return [];
}

function isExpired(expiresAt) {
  if (!expiresAt) return false;
  const expires = new Date(expiresAt).getTime();
  if (Number.isNaN(expires)) return false;
  return expires < Date.now();
}

function buildEmptyMemory(reason, request, config) {
  return {
    found: false,
    usable: false,
