}

const config =
  $('Load Memory Schema Config').first().json.memory_service_config || {};

const request =
  $('Normalize M4 Request').first().json.m4_request || {};

const lookupPolicy = config.lookup_policy || {
  require_active_status: true,
  enforce_expiration: true,
  validate_user_match: true
};

const row = items[0]?.json || {};
const hasMemory = Boolean(row.session_id);

if (!hasMemory) {
  return [
    {
      json: {
        schema_version: 'dalia.m4.memory_result.v1',
        operation: 'get_session_memory',
        result_type: 'memory_lookup_result',
        success: true,
        session_memory: buildEmptyMemory('memory_not_found', request, config),
        passthrough: request.passthrough || {}
      }
    }
  ];
}

const userMatches =
  !lookupPolicy.validate_user_match ||
  !request.lookup?.user_id ||
  clean(row.user_id) === clean(request.lookup.user_id);

const activeStatus =
  !lookupPolicy.require_active_status ||
  clean(row.session_status || 'active') === 'active';

const expired =
  lookupPolicy.enforce_expiration &&
  isExpired(row.expires_at);

let usable = true;
let reason = 'memory_found';

if (!userMatches) {
  usable = false;
  reason = 'user_mismatch';
}

if (!activeStatus) {
  usable = false;
  reason = 'session_not_active';
}

if (expired) {
  usable = false;
  reason = 'session_expired';
}

const lastProductsRecommended = ensureArray(row.last_products_recommended);
const currentFocusProducts = ensureArray(row.current_focus_products);
const recentTurns = ensureArray(row.recent_turns)
  .slice(-(config.session_policy?.max_recent_turns || 5));

const sessionMemory = {
  found: true,
  usable,
  reason,

  identity: {
    session_id: clean(row.session_id),
    conversation_id: clean(row.conversation_id),
    user_id: clean(row.user_id),
    channel: clean(row.channel),
    display_name: clean(row.display_name)
  },

  commercial_context: {
    last_intent: clean(row.last_intent),
    last_advisor_mode: clean(row.last_advisor_mode),
    last_user_message: clean(row.last_user_message),
    last_response_type: clean(row.last_response_type),
    last_next_step: clean(row.last_next_step),

    last_product_consulted: clean(row.last_product_consulted),
    last_products_recommended: lastProductsRecommended,

    last_category_consulted: clean(row.last_category_consulted),
    last_preference_detected: clean(row.last_preference_detected),
    last_city_detected: clean(row.last_city_detected),

    catalog_matched: Boolean(row.catalog_matched),
    last_purchase_signal_detected: Boolean(row.last_purchase_signal_detected),
    last_handoff_suggested: Boolean(row.last_handoff_suggested)
  },

  reference_context: {
    current_focus_product: clean(row.current_focus_product),
    current_focus_products: currentFocusProducts,
    can_resolve_contextual_references: Boolean(
      row.can_resolve_contextual_references
    ),
    supported_references: config.reference_resolution?.supported_references || []
  },

  recent_turns: recentTurns,

  lifecycle: {
    session_status: clean(row.session_status),
    created_at: row.created_at || '',
    updated_at: row.updated_at || '',
    expires_at: row.expires_at || ''
  },

  control: {
    source: 'supabase',
    table: config.storage?.table || 'dalia_session_memory',
    retrieved_at: new Date().toISOString()
  }
};

return [
  {
    json: {
      schema_version: 'dalia.m4.memory_result.v1',
