function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function ensureArray(value) {
 if (Array.isArray(value)) return value;
 if (!value) return [];

 if (typeof value === 'string') {
   try {
     const parsed = JSON.parse(value);
     return Array.isArray(parsed) ? parsed : [];
   } catch (e) {
     return [];
   }
 }

 return [];
}

function productNames(products) {
 return ensureArray(products)
   .map(product => {
     if (typeof product === 'string') return product;
     return product.display_name || product.product_name || '';
   })
   .filter(Boolean);
}

function unique(values) {
 return [...new Set(values.filter(Boolean))];
}

const row = items[0]?.json || {};
const request =
 $('Normalize M4 Request').first().json.m4_request || {};

const closeRequest = request.close_request || {};
const closeReason = clean(closeRequest.close_reason || 'manual_or_timeout');
const closedAt = new Date().toISOString();

const recommendedProducts = productNames(row.last_products_recommended);
const focusProducts = productNames(row.current_focus_products);

const lastProducts = unique([
 row.last_product_consulted,
 ...recommendedProducts,
 ...focusProducts
]).slice(0, 5);

const lastInterest =
 clean(row.last_preference_detected) ||
 clean(row.last_category_consulted) ||
 clean(row.last_product_consulted);

const purchaseSignal = Boolean(row.last_purchase_signal_detected);
const handoffSuggested = Boolean(row.last_handoff_suggested);

let summary = '';

if (lastInterest) {
 summary += `El usuario mostró interés en ${lastInterest}. `;
} else {
 summary += 'El usuario tuvo una interacción comercial sin una preferencia específica registrada. ';
}

if (lastProducts.length > 0) {
 summary += `Se consultaron o recomendaron productos como ${lastProducts.join(', ')}. `;
}

if (purchaseSignal) {
 summary += 'Se detectó una señal de intención de compra. ';
} else {
 summary += 'No se detectó intención de compra confirmada. ';
}

if (handoffSuggested) {
 summary += 'Se sugirió posible atención humana. ';
}

summary = summary.trim();

const sessionStatus =
 closeReason === 'timeout' || closeReason === 'expired'
   ? 'expired'
   : 'closed';

const sessionSummary = {
 schema_version: 'dalia.m4.session_summary.v1',
 session_id: clean(row.session_id),
 conversation_id: clean(row.conversation_id),
 user_id: clean(row.user_id),
 channel: clean(row.channel),
 display_name: clean(row.display_name),

 close_reason: closeReason,
 session_status: sessionStatus,

 summary,
 last_interest: lastInterest,
 last_product_consulted: clean(row.last_product_consulted),
 last_products: lastProducts,

 last_intent: clean(row.last_intent),
 last_response_type: clean(row.last_response_type),
 last_next_step: clean(row.last_next_step),

 purchase_signal_detected: purchaseSignal,
 handoff_suggested: handoffSuggested,

 created_at: row.created_at || '',
 updated_at: row.updated_at || '',
 closed_at: closedAt
};

return [
 {
   json: {
     schema_version: 'dalia.m4.memory_result.v1',
     operation: 'close_session_summary',
     result_type: 'session_summary_candidate',
     success: true,
     close_status: 'summary_built',
     session_status: sessionStatus,
     session_id: row.session_id,
     close_reason: closeReason,
     closed_at: closedAt,
     session_summary: sessionSummary
   }
 }
];

