  clean(row.session_status || 'active') === 'active';

const expired =
  lookupPolicy.enforce_expiration && isExpired(row.expires_at);

let usable = true;
let reason = 'memory_found';

if (!userMatches)  { usable = false; reason = 'user_mismatch'; }
if (!activeStatus) { usable = false; reason = 'session_not_active'; }
if (expired)       { usable = false; reason = 'session_expired'; }

const lastProductsRecommended = ensureArray(row.last_products_recommended);
const currentFocusProducts    = ensureArray(row.current_focus_products);
const recentTurns = ensureArray(row.recent_turns)
  .slice(-(config.session_policy?.max_recent_turns || 5));

const sessionMemory = {
  found: true,
  usable,
  reason,
  identity: {
    session_id:      clean(row.session_id),
    conversation_id: clean(row.conversation_id),
    user_id:         clean(row.user_id),
    channel:         clean(row.channel),
    display_name:    clean(row.display_name)
  },
  commercial_context: {
    last_intent:              clean(row.last_intent),
    last_advisor_mode:        clean(row.last_advisor_mode),
    last_user_message:        clean(row.last_user_message),
    last_response_type:       clean(row.last_response_type),
    last_next_step:           clean(row.last_next_step),
    last_product_consulted:   clean(row.last_product_consulted),
    last_products_recommended: lastProductsRecommended,
    last_category_consulted:  clean(row.last_category_consulted),
    last_preference_detected: clean(row.last_preference_detected),
    last_city_detected:       clean(row.last_city_detected),
    catalog_matched:          Boolean(row.catalog_matched),
    last_purchase_signal_detected: Boolean(row.last_purchase_signal_detected),
    last_handoff_suggested:   Boolean(row.last_handoff_suggested)
  },
  reference_context: {
    can_resolve_contextual_references: usable,
    current_focus_product:  clean(row.current_focus_product || row.last_product_consulted),
    current_focus_products: currentFocusProducts.length > 0
      ? currentFocusProducts
      : lastProductsRecommended,
    supported_references: config.reference_resolution?.supported_references || []
  },
  recent_turns: recentTurns,
  lifecycle: {
    session_status: clean(row.session_status),
    created_at:     clean(row.created_at),
    updated_at:     clean(row.updated_at),
    expires_at:     clean(row.expires_at)
  },
  control: {
    source:       'supabase',
    table:        config.storage?.table || 'dalia_session_memory',
    retrieved_at: new Date().toISOString()
  }
};

return [{
  json: {
    schema_version: 'dalia.m4.memory_result.v1',
    operation: 'get_turn_context',
    result_type: 'memory_lookup_result',
    success: true,
    session_memory: sessionMemory,
    passthrough: request.passthrough || {}
  }
}];

const input = items[0]?.json || {};

// Qdrant devuelve los resultados en result o body.result
const rawResults = input.result || input?.body?.result || [];

const SCORE_HIGH   = 0.80;
const SCORE_MEDIUM = 0.65;
const MAX_MEMORIES = 3;

// Filtrar por score mínimo y ordenar desc
const filtered = rawResults
  .filter(r => typeof r.score === 'number' && r.score >= SCORE_MEDIUM)
  .sort((a, b) => b.score - a.score)
  .slice(0, MAX_MEMORIES);

// Deduplicar por memory_type + product_id
const seen = new Set();
const deduped = [];
for (const r of filtered) {
  const key = (r.payload?.memory_type || '') + '_' + (r.payload?.product_id || 'no_product');
  if (!seen.has(key)) {
    seen.add(key);
    deduped.push(r);
  }
}

const topScore   = deduped.length > 0 ? deduped[0].score : 0;
const hasUsable  = deduped.length > 0;
const confidence = topScore >= SCORE_HIGH
  ? 'high'
  : topScore >= SCORE_MEDIUM
    ? 'medium'
    : 'low';

const memories = deduped.map(r => ({
  memory_type:  r.payload?.memory_type  || 'unknown',
  memory_text:  r.payload?.memory_text  || '',
  product_name: r.payload?.product_name || null,
  product_id:   r.payload?.product_id   || null,
  category:     r.payload?.category     || null,
  city:         r.payload?.city         || null,
  score:        parseFloat((r.score).toFixed(4)),
  confidence:   r.score >= SCORE_HIGH ? 'high' : 'medium'
}));

const customerVectorMemory = {
  retrieved:     true,
  usable:        hasUsable,
  top_score:     parseFloat(topScore.toFixed(4)),
  confidence:    confidence,
  results_count: deduped.length,
  memories:      memories
};

return [{
  json: {
    ...input,
    customer_vector_memory: customerVectorMemory
  }
}];

const input = items[0]?.json || {};
const vm = input.customer_vector_memory || {};

if (!vm.usable || !vm.memories || vm.memories.length === 0) {
  return [{
    json: {
      ...input,
      soft_customer_context: {
        has_relevant_memory: false,
        memory_confidence:   'none',
        safe_summary:        null,
        conversation_cues:   [],
        do_not_say:          []
      }
    }
  }];
}

const memories = vm.memories;

const productMems  = memories.filter(m =>
  m.memory_type === 'product_interest' || m.memory_type === 'purchase_context'
);
const prefMems     = memories.filter(m => m.memory_type === 'preference');
const cityMems     = memories.filter(m => m.memory_type === 'city_or_location');
const handoffMems  = memories.filter(m => m.memory_type === 'handoff_context');

// Construir safe_summary
const summaryParts = [];

if (productMems.length > 0) {
  const pm = productMems[0];
  summaryParts.push(
    pm.product_name
      ? `El cliente había mostrado interés en ${pm.product_name}.`
      : pm.memory_text.substring(0, 120)
  );
}
if (prefMems.length > 0) {
  summaryParts.push('Mostró preferencias por productos sostenibles o de uso diario.');
}
if (cityMems.length > 0 && cityMems[0].city) {
  summaryParts.push(
    `Ciudad mencionada anteriormente: ${cityMems[0].city} (pendiente de confirmar).`
  );
}
if (handoffMems.length > 0) {
  summaryParts.push('Ya solicitó atención humana en una conversación anterior.');
}

const safeSummary = summaryParts.join(' ').trim() || null;

// Construir conversation_cues
const cues = [];

for (const m of memories) {
  if ((m.memory_type === 'product_interest' || m.memory_type === 'purchase_context') && m.product_name) {
    cues.push(
      `Puede mencionar ${m.product_name} como opción si el cliente pregunta por productos similares.`
    );
  }
  if (m.memory_type === 'preference') {
    cues.push(
      'Puede enfocar recomendaciones en productos sostenibles sin afirmarlo como certeza.'
    );
  }
  if (m.memory_type === 'city_or_location' && m.city) {
    cues.push(
      `Puede preguntar "¿confirmamos ${m.city} como ciudad de entrega?" en vez de asumirlo.`
    );
  }
  if (m.memory_type === 'purchase_context' && m.product_name) {
    cues.push(
      `Hay contexto de compra iniciada para ${m.product_name}. Confirmar con el cliente antes de retomar.`
    );
  }
  if (m.memory_type === 'handoff_context') {
    cues.push(
      'El cliente ya solicitó agente humano antes. Responder con especial atención.'
    );
  }
  if (m.memory_type === 'unresolved_need') {
    cues.push(
      `Hay una necesidad sin resolver registrada: "${m.memory_text.substring(0, 80)}". Puede retomarse si es relevante.`
    );
  }
}

return [{
  json: {
    ...input,
    soft_customer_context: {
      has_relevant_memory: true,
      memory_confidence:   vm.confidence,
      safe_summary:        safeSummary,
      conversation_cues:   cues,
      do_not_say: [
        'Te tengo guardado',
        'Sé que siempre compras',
        'Tengo todo tu historial',
        'Voy a usar tu dirección anterior sin confirmar',
        'Ya sé lo que buscas',
        'Recuerdo que la última vez'
      ]
    }
  }
}];

function safeGet(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

const sessionBranch = safeGet('Normalize Retrieved Session Memory (Turn Context)');
const vectorBranch  = safeGet('Build Soft Customer Context');

const request = $('Normalize M4 Request').first().json.m4_request || {};

return [{
  json: {
    session_memory: sessionBranch.session_memory || {
      found: false,
      usable: false,
      reason: 'memory_not_found'
    },
    soft_customer_context: vectorBranch.soft_customer_context || {
