function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function inferOperation(input) {
  if (input.operation) return clean(input.operation);

  if (input.schema_version === 'dalia.m3_to_m4.memory_update.v1') {
    return 'upsert_session_memory';
  }

  if (input.memory_update) {
    return 'upsert_session_memory';
  }

  if (input.lookup || input.current_turn) {
    return 'get_session_memory';
  }

  if (input.close_request || input.session_summary_request) {
    return 'close_session_summary';
  }

  if (input.operation === 'save_vector_memory' || input.vector_memory_save_request) {
    return 'save_vector_memory';
  }

  if (input.operation === 'retrieve_vector_memory' || input.vector_memory_retrieve_request) {
    return 'retrieve_vector_memory';
  }

  if (input.operation === 'get_turn_context') {
    return 'get_turn_context';
  }

  return 'unknown';
}

function normalizeLookup(input) {
  const lookup = input.lookup || {};
  const trace = input.trace || input.m2_input?.trace || {};
  const context = input.context || input.m2_input?.context || {};
  const memoryUpdate = input.memory_update || {};

  return {
    session_id: clean(
      lookup.session_id ||
      trace.session_id ||
      memoryUpdate.session_id ||
      input.session_id
    ),
    conversation_id: clean(
      lookup.conversation_id ||
      trace.conversation_id ||
      memoryUpdate.conversation_id ||
      input.conversation_id
    ),
    user_id: clean(
      lookup.user_id ||
      context.user_id ||
      memoryUpdate.user_id ||
      input.user_id
    ),
    channel: clean(
      lookup.channel ||
      context.channel ||
      memoryUpdate.channel ||
      input.channel
    )
  };
}

function normalizeCurrentTurn(input) {
  const current = input.current_turn || input.input || input.message || {};
  const memoryUpdate = input.memory_update || {};

  return {
    message_id: clean(current.message_id || current.id),
    type: clean(current.type),
    text: clean(
      current.text ||
      current.normalized_text ||
      memoryUpdate.last_user_message
    ),
    timestamp: clean(current.timestamp || memoryUpdate.updated_at)
  };
}

function normalizeMemoryUpdate(input) {
  const memoryUpdate = input.memory_update || {};

  return {
    conversation_id: clean(memoryUpdate.conversation_id),
    session_id: clean(memoryUpdate.session_id),
    user_id: clean(memoryUpdate.user_id),
    channel: clean(memoryUpdate.channel),
    display_name: clean(memoryUpdate.display_name),

    intent: clean(memoryUpdate.intent),
    advisor_mode: clean(memoryUpdate.advisor_mode),
    last_user_message: clean(memoryUpdate.last_user_message),
    response_type: clean(memoryUpdate.response_type),
    next_step: clean(memoryUpdate.next_step),

    product_consulted: clean(memoryUpdate.product_consulted),
    last_products_recommended: Array.isArray(memoryUpdate.last_products_recommended)
      ? memoryUpdate.last_products_recommended
      : [],

    category_consulted: clean(memoryUpdate.category_consulted),
    preference_detected: clean(memoryUpdate.preference_detected),
    city_detected: clean(memoryUpdate.city_detected),

    catalog_matched: Boolean(memoryUpdate.catalog_matched),
    purchase_signal_detected: Boolean(memoryUpdate.purchase_signal_detected),
    handoff_suggested: Boolean(memoryUpdate.handoff_suggested),

    updated_at: clean(memoryUpdate.updated_at) || new Date().toISOString()
  };
}

function normalizeCloseRequest(input) {
  const closeRequest = input.close_request || input.session_summary_request || {};
  const lookup = normalizeLookup(input);

  return {
    session_id: clean(closeRequest.session_id || lookup.session_id),
    conversation_id: clean(closeRequest.conversation_id || lookup.conversation_id),
    user_id: clean(closeRequest.user_id || lookup.user_id),
    close_reason: clean(closeRequest.close_reason || 'manual_or_timeout'),
    requested_at: clean(closeRequest.requested_at) || new Date().toISOString()
  };
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};

const operation = inferOperation(input);

const m4Request = {
  schema_version: config.contracts?.request_schema_version || 'dalia.m4.memory_request.v1',
  operation,

  lookup: normalizeLookup(input),
  current_turn: normalizeCurrentTurn(input),
  memory_update: normalizeMemoryUpdate(input),
  close_request: normalizeCloseRequest(input),

  requested_at: new Date().toISOString(),
  passthrough: input.passthrough || input
};

return [
  {
    json: {
      ...input,
      m4_request: m4Request
    }
  }
];

function isEmpty(value) {
  return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};
const request = input.m4_request || {};

const errors = [];
const warnings = [];

const supportedOperations = config.supported_operations || [];

if (!supportedOperations.includes(request.operation)) {
  errors.push('unsupported_operation');
}

if (request.operation === 'get_session_memory') {
  if (isEmpty(request.lookup?.session_id)) {
    errors.push('missing_lookup_session_id');
  }

  if (isEmpty(request.lookup?.user_id)) {
    warnings.push('missing_lookup_user_id');
  }
}

if (request.operation === 'upsert_session_memory') {
  const memory = request.memory_update || {};

  if (isEmpty(memory.session_id)) {
    errors.push('missing_memory_session_id');
  }

  if (isEmpty(memory.conversation_id)) {
    errors.push('missing_memory_conversation_id');
  }

  if (isEmpty(memory.user_id)) {
    errors.push('missing_memory_user_id');
  }

  if (
    isEmpty(memory.product_consulted) &&
    (!Array.isArray(memory.last_products_recommended) || memory.last_products_recommended.length === 0) &&
    isEmpty(memory.preference_detected) &&
    isEmpty(memory.city_detected)
  ) {
    warnings.push('memory_update_has_no_commercial_signal');
  }
}

if (request.operation === 'close_session_summary') {
  if (isEmpty(request.close_request?.session_id)) {
    errors.push('missing_close_session_id');
  }
}

return [
  {
    json: {
      ...input,
      m4_request_validation: {
        valid: errors.length === 0,
        errors,
        warnings
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      branch_context: {
        branch: 'get_session_memory',
        configured_in_task: 1,
        next_task: 3,
        status: 'branch_entry_ready'
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      branch_context: {
        branch: 'upsert_session_memory',
        configured_in_task: 1,
        next_task: 2,
        status: 'branch_entry_ready'
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      branch_context: {
        branch: 'close_session_summary',
        configured_in_task: 1,
        next_task: 5,
        status: 'branch_entry_ready'
      }
    }
  }
];

const input = items[0]?.json || {};

return [
  {
    json: {
      schema_version: 'dalia.m4.memory_result.v1',
      operation: input.m4_request?.operation || 'unknown',
      success: false,
      result_type: 'invalid_request',
      errors: input.m4_request_validation?.errors || ['unsupported_operation'],
      warnings: input.m4_request_validation?.warnings || [],
      session_memory: {
        found: false,
        usable: false,
        reason: 'invalid_m4_request'
      }
    }
  }
];

function nowIso() {
  return new Date().toISOString();
}

function isValidDate(str) {
  if (!str) return false;
  return !isNaN(new Date(str).getTime());
}

function addHours(date, hours) {
  const d = new Date(date);
  if (isNaN(d.getTime())) return nowIso();
  const h = parseInt(hours, 10);
  d.setHours(d.getHours() + (isNaN(h) ? 24 : h));
  return d.toISOString();
}

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function normalizeProductList(value, maxItems = 5) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map(item => {
        if (typeof item === 'string') {
          return {
            product_id: '',
            display_name: item,
            category: '',
            color: ''
          };
        }

        return {
          product_id: item.product_id || item.sku || '',
          display_name: item.display_name || item.product_name || '',
          category: item.category || '',
          color: item.color || ''
        };
      })
      .filter(item => item.display_name)
      .slice(0, maxItems);
  }

  return [];
}

const input = items[0]?.json || {};
const config = input.memory_service_config || {};
const request = input.m4_request || {};
