const input = $input.first().json;

// Qdrant devuelve resultados en input.result o input.body.result
const rawResults = input.result || input?.body?.result || [];

const SCORE_HIGH   = 0.80;
const SCORE_MEDIUM = 0.65;
const MAX_MEMORIES = 3;

// Filtrar y ordenar
const filtered = rawResults
  .filter(r => r.score >= SCORE_MEDIUM)
  .sort((a, b) => b.score - a.score)
  .slice(0, MAX_MEMORIES);

// Deduplicar por memory_type (mantener el de mayor score)
const seen = new Set();
const deduped = [];
for (const r of filtered) {
  const key = r.payload?.memory_type + "_" + (r.payload?.product_id || "");
  if (!seen.has(key)) {
    seen.add(key);
    deduped.push(r);
  }
}

const topScore     = deduped.length > 0 ? deduped[0].score : 0;
const hasUsable    = deduped.length > 0;
const confidence   = topScore >= SCORE_HIGH ? "high" : topScore >= SCORE_MEDIUM ? "medium" : "low";

const memories = deduped.map(r => ({
  memory_type:  r.payload?.memory_type  || "unknown",
  memory_text:  r.payload?.memory_text  || "",
  product_name: r.payload?.product_name || null,
  product_id:   r.payload?.product_id   || null,
  category:     r.payload?.category     || null,
  city:         r.payload?.city         || null,
  score:        parseFloat((r.score).toFixed(4)),
  confidence:   r.score >= SCORE_HIGH ? "high" : "medium"
}));

const customerVectorMemory = {
  retrieved:    true,
  usable:       hasUsable,
  top_score:    parseFloat(topScore.toFixed(4)),
  confidence:   confidence,
  results_count: deduped.length,
  memories:     memories
};

return [{ json: { ...input, customer_vector_memory: customerVectorMemory } }];

const input = $input.first().json;
const vm    = input.customer_vector_memory || {};

if (!vm.usable || vm.memories.length === 0) {
  return [{
    json: {
      ...input,
      soft_customer_context: {
        has_relevant_memory: false,
        memory_confidence:   "none",
        safe_summary:        null,
        conversation_cues:   [],
        do_not_say:          []
      }
    }
  }];
}

const memories = vm.memories;

// Construir resumen seguro
const productMemories = memories.filter(m => m.memory_type === "product_interest" || m.memory_type === "purchase_context");
const prefMemories    = memories.filter(m => m.memory_type === "preference");
const cityMemories    = memories.filter(m => m.memory_type === "city_or_location");

let summaryParts = [];

if (productMemories.length > 0) {
  const pm = productMemories[0];
  summaryParts.push(pm.product_name
    ? `El cliente había mostrado interés en ${pm.product_name}.`
    : pm.memory_text.substring(0, 120));
}
if (prefMemories.length > 0) {
  summaryParts.push("Mostró preferencias por productos sostenibles o de uso diario.");
}
if (cityMemories.length > 0 && cityMemories[0].city) {
  summaryParts.push(`Ciudad mencionada anteriormente: ${cityMemories[0].city} (pendiente de confirmar).`);
}

const safeSummary = summaryParts.join(" ").trim();

// Construir conversation_cues según los recuerdos
const cues = [];
for (const m of memories) {
  if (m.memory_type === "product_interest" && m.product_name) {
    cues.push(`Puede mencionar ${m.product_name} como opción si el cliente pregunta por productos similares.`);
  }
  if (m.memory_type === "preference") {
    cues.push("Puede enfocar recomendaciones en productos sostenibles sin afirmarlo como certeza.");
  }
  if (m.memory_type === "city_or_location" && m.city) {
    cues.push(`Puede preguntar "¿confirmamos ${m.city} como ciudad de entrega?" en vez de asumirlo.`);
  }
  if (m.memory_type === "purchase_context" && m.product_name) {
    cues.push(`Hay contexto de compra iniciada para ${m.product_name}. Confirmar antes de retomar.`);
  }
}

const softCustomerContext = {
  has_relevant_memory: true,
  memory_confidence:   vm.confidence,
  safe_summary:        safeSummary,
  conversation_cues:   cues,
  do_not_say: [
    "Te tengo guardado",
    "Sé que siempre compras",
    "Tengo todo tu historial",
    "Voy a usar tu dirección anterior sin confirmar",
    "Ya sé que quieres comprar"
  ]
};

return [{ json: { ...input, soft_customer_context: softCustomerContext } }];

