const errors = [];
const warnings = [];

// acepta tanto get_session_memory (compatibilidad) como get_turn_context
if (!['get_session_memory', 'get_turn_context'].includes(request.operation)) {
  errors.push('invalid_branch_operation');
}

if (isEmpty(request.lookup?.session_id)) {
