}

// Contexto semántico adicional según señales del mensaje
const msgLower = userMessage.toLowerCase();

const waterSignals = ['agua', 'llevar', 'termo', 'botella', 'recipiente', 'bebida', 'tomar'];
if (waterSignals.some(s => msgLower.includes(s))) {
  parts.push('Contexto adicional: recipientes para líquidos, termos, productos para llevar bebidas.');
}

const ecoSignals = ['eco', 'natural', 'bambú', 'bambu', 'sostenible', 'sustentable', 'orgánico', 'organico'];
if (ecoSignals.some(s => msgLower.includes(s))) {
  parts.push('Contexto adicional: productos ecológicos, sostenibles, de materiales naturales.');
}

const careSignals = ['cuidado', 'personal', 'higiene', 'bucal', 'dental', 'piel', 'cabello'];
if (careSignals.some(s => msgLower.includes(s))) {
  parts.push('Contexto adicional: productos de cuidado personal, higiene, bienestar.');
}

const purchaseSignals = ['comprar', 'llevar', 'pagar', 'precio', 'costo', 'cuánto', 'cuanto', 'quiero'];
if (purchaseSignals.some(s => msgLower.includes(s))) {
