      do_not_say:          []
    },
    customer_vector_memory: vectorBranch.customer_vector_memory || {
      retrieved: false,
      usable:    false,
      memories:  []
    },
    passthrough: sessionBranch.passthrough || request.passthrough || {}
  }
}];

const input = items[0]?.json || {};

return [{
  json: {
    schema_version: 'dalia.m4.memory_result.v1',
    operation:      'get_turn_context',
    result_type:    'turn_context_result',
    success:        true,
    session_memory:         input.session_memory,
    soft_customer_context:  input.soft_customer_context,
    customer_vector_memory: input.customer_vector_memory,
    passthrough:            input.passthrough || {}
  }
}];

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function extractSummaryText(value) {
  if (!value) return '';
  // Si es string, usarlo directo
  if (typeof value === 'string') return value.trim();
  // Si es objeto vacío {} o array vacío, devolver ''
  if (typeof value === 'object') {
    const str = JSON.stringify(value);
    if (str === '{}' || str === '[]' || str === 'null') return '';
    // Si por alguna razón llegara con contenido, intentar extraer
    return clean(value.text || value.summary || '');
  }
  return '';
}

const input = items[0]?.json || {};
const request = input.m4_request || {};
const turn = request.turn || {};
const ctx = request.context || {};

// ── LEER FILA DE SUPABASE ──
// Fetch Current Conversation Summary devuelve array — tomar primer elemento
const sessionRow = input;

const currentSummary = extractSummaryText(sessionRow.session_summary);
const turnCount      = Number(sessionRow.summary_turn_count || 0);

// ── CONSTRUIR BLOQUE DEL TURNO ACTUAL ──
const userMessage    = clean(turn.user_message    || turn.text);
const daliaResponse  = clean(turn.dalia_response  || '');
const intent         = clean(turn.intent          || '');
const productName    = clean(turn.product_consulted || turn.product_name || '');
const productId      = clean(turn.product_id      || '');
const category       = clean(turn.category        || '');
const cityDetected   = clean(turn.city_detected   || '');
const memoryTextHint = clean(turn.memory_text_hint || '');
const purchaseSignal = Boolean(turn.purchase_signal_detected);
const handoffSignal  = Boolean(turn.handoff_suggested);

let turnBlock = '';

if (memoryTextHint && memoryTextHint.length > 20) {
  turnBlock = memoryTextHint;
} else {
  const parts = [];

  if (userMessage) {
    parts.push(`Cliente dijo: "${userMessage}"`);
  }
  if (daliaResponse) {
    const snippet = daliaResponse.substring(0, 200);
    parts.push(`DALIA respondió: "${snippet}${daliaResponse.length > 200 ? '...' : ''}"`);
  }
  if (productName) {
    parts.push(
      `Producto en juego: ${productName}` +
      `${productId ? ` (ID: ${productId})`       : ''}` +
      `${category  ? ` — categoría: ${category}` : ''}`
    );
  }
  if (cityDetected) {
    parts.push(`Ciudad mencionada: ${cityDetected}`);
  }
  if (intent) {
    const intentLabels = {
      product_inquiry:   'consulta de producto',
      product_search:    'búsqueda de producto',
      purchase_intent:   'intención de compra',
      preference_signal: 'señal de preferencia',
      unresolved_need:   'necesidad no resuelta',
      handoff_request:   'solicitud de agente humano',
      general_inquiry:   'consulta general'
    };
    parts.push(`Intención: ${intentLabels[intent] || intent}`);
  }
  if (purchaseSignal) parts.push('Señal de compra detectada.');
  if (handoffSignal)  parts.push('Se activó handoff a agente humano.');

  turnBlock = parts.join('. ').trim();
}

// Si el turno no tiene información útil, marcar para skip
const hasMeaningfulContent = Boolean(
  productName || cityDetected || purchaseSignal ||
  handoffSignal ||
  (intent && intent !== 'general_inquiry' && intent !== 'uncertain') ||
  (userMessage && userMessage.length > 3 && !['hola','ok','sí','si','no','gracias'].includes(userMessage.toLowerCase().trim()))
);

return [{
  json: {
    ...input,
    summary_context: {
      current_summary:        currentSummary,
      current_turn_text:      turnBlock,
      has_meaningful_content: hasMeaningfulContent,
      turn_count:             turnCount,
      conversation_id:        clean(ctx.conversation_id || sessionRow.conversation_id),
      session_id:             clean(ctx.session_id      || sessionRow.session_id),
      user_id:                clean(ctx.user_id         || sessionRow.user_id),
      business_id:            clean(ctx.business_id)    || 'business_demo',
      channel:                clean(ctx.channel         || sessionRow.channel) || 'whatsapp'
    }
  }
}];

const input = items[0]?.json || {};

// AI Agent devuelve el texto en .output
const rawResponse = clean(
  input.output ||
  input.text   ||
  input.response ||
  ''
);

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

const updatedSummary = rawResponse.trim();

const finalSummary = updatedSummary.length > 10
  ? updatedSummary
  : (input.summary_context?.current_summary || '');

return [{
  json: {
    ...input,
    updated_summary: finalSummary
  }
}];
